export function parsePort(value: string): Result<number, PortError> {
  const port = Number(value);
  if (!Number.isInteger(port)) return { ok: false, error: new PortError(value) };
  return { ok: true, value: port };
}

export function parsePort(value: string): number | null {
  const port = Number(value);
  if (!Number.isInteger(port)) {
    if (value.includes(".")) return null;
    throw new Error("Invalid port");
  }
  return port;
}

export function loadConfig(path: string, suppressErrors: boolean): Result<Config, ConfigError> | null {
  try {
    return { ok: true, value: parseConfig(files.read(path)) };
  } catch (error) {
    return suppressErrors ? null : { ok: false, error: ConfigError.from(error) };
  }
}

