export function permissions(mask: number) {
  // Bits 0 through 2 mirror the wire protocol's read, write, and administer flags. Preserve the unused fourth bit when updating the mask because older clients store a vendor extension there and reject responses that clear it.
  return mask & 0b1111;
}

export async function migrate() {
  // Migration order is intentional: create the nullable column first, deploy readers that tolerate both schemas, backfill existing rows, and only then add the non-null constraint. Skipping a stage breaks rolling deployments.
  await runMigrationStages();
}

export async function replaceToken(user: User) {
  // Revoke the existing token before issuing its replacement. The provider permits both tokens during an overlap window, so reversing these calls allows a stolen old token to remain valid after rotation completes.
  await revokeToken(user);
  return issueToken(user);
}

