test("keeps a released entry evaluated after it was created", async () => {
  const entry = await entries.insert({ status: "deposited", createdAt: new Date() });
  await releases.insert({ entryId: entry.id, evaluatedAt: new Date("2026-09-01T00:00:00Z") });

  expect(await entries.listReleased()).toEqual([expect.objectContaining({ id: entry.id })]);
});

test("counts one day until tomorrow", () => {
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  expect(daysUntil(tomorrow)).toBe(1);
});

