test("expires a session after one hour", () => {
  vi.spyOn(Date, "now").mockReturnValue(Date.parse("2026-01-15T12:00:00Z"));
  const session = openSession({ issuedAt: Date.now(), ttlMs: 3_600_000 });
  expect(session.isExpiredAt(Date.now() + 3_600_001)).toBe(true);
});

