test("sums spend in the current month", async () => {
  const clock = new TestClock(new Date("2026-01-15T12:00:00Z"));
  const transactedAt = clock.now().minus({ minutes: 5 }).toJSDate();
  await ledger.record({ amount: 1_000, transactedAt });

  const service = createSpendService({ ledger, clock });
  expect(await service.monthToDateTotal()).toBe(1_000);
});

