  expect(period.label).toBe("August 2026");
});

test("stamps the token with the issue time", () => {
  const token = issueToken({ subject: "user-1", now: () => new Date("2026-01-15T12:00:00Z") });
  expect(token.issuedAt).toEqual(new Date("2026-01-15T12:00:00Z"));
});

test("stamps events with the time they were created", () => {
  const before = Date.now();
  const event = createEvent({ type: "created" });
  const after = Date.now();
  expect(event.createdAt.getTime()).toBeGreaterThanOrEqual(before);
  expect(event.createdAt.getTime()).toBeLessThanOrEqual(after);
});

test("records who approved the request", async () => {
  const clock = new TestClock(new Date("2026-01-15T12:00:00Z"));
  const request = await createRequest({ submittedBy: "user-1", correlationId: `req-${Date.now()}` });
  await approve(request.id, { approver: "user-2", clock });
  expect(await auditTrail(request.id)).toEqual([
    expect.objectContaining({ actor: "user-2", action: "approved", at: clock.now().toJSDate() }),
  ]);
});

